app.post([
  "/api/stripe/create-checkout-session",
  "/api/stripe/create-checkout-session/",
  "/stripe/create-checkout-session",
  "/stripe/create-checkout-session/",
  "/api/create-checkout-session",
  "/api/create-checkout-session/",
  "/create-checkout-session",
  "/create-checkout-session/"
], requireAuth, async (req: AuthRequest, res) => {
  const authUserId = req.user?.uid || (req.user as any)?.user_id;
  if (!authUserId) {
    return res.status(401).json({ 
      success: false,
      error: "تعذر التحقق من جلسة حسابك. يرجى تحديث الجلسة والمحاولة مرة أخرى." 
    });
  }

  // Security Policy Check: Mock authentication tokens must NEVER create Live Stripe sessions
  const stripeKeys = resolveStripeKeys();
  const isMockAuth = Boolean((req as any).isMockAuth || (req.user as any)?.isMockUser);
  const isLiveStripe = Boolean(
    stripeKeys.secretKey?.startsWith("sk_live_") || 
    stripeKeys.secretKey?.startsWith("rk_live_") ||
    stripeKeys.publishableKey?.startsWith("pk_live_")
  );

  if (isMockAuth && isLiveStripe) {
    console.error("[SECURITY VIOLATION BLOCKED] Attempt to initiate Live Stripe checkout session with mock authentication token.");
    return res.status(403).json({
      success: false,
      code: "MOCK_AUTH_LIVE_STRIPE_BLOCKED",
      error: "Security Violation: Mock authentication tokens cannot be used to create Live Stripe sessions. Real authenticated user session required.",
      userFriendlyMessage: "إجراء أمني: لا يمكن استخدام جلسات الاختبار الوهمية لإنشاء معاملات دفع حية."
    });
  }

  // Concurrency guard to prevent multiple simultaneous session requests
  if (inFlightCheckoutUsers.has(authUserId)) {
    return res.status(429).json({
      success: false,
      error: "جاري معالجة طلب اشتراك سابق. يرجى الانتظار بضع ثوانٍ."
    });
  }

  inFlightCheckoutUsers.add(authUserId);

  try {
    const { plan = "Professional", billingCycle = "annual", companyName } = req.body;

    const db = readDb();
    let user = db.users.find((u: any) => u.id === authUserId);
    if (!user) {
      try {
        const userDoc = await adminDb.collection("users").doc(authUserId).get();
        if (userDoc && userDoc.exists) {
          user = userDoc.data();
        }
      } catch (fsErr) {
        console.warn("[CHECKOUT] Firestore user lookup warning:", fsErr);
      }
    }

    const finalUserId = authUserId;
    const finalUserEmail = req.user?.email || user?.email || "";
    const finalCompanyName = companyName || user?.companyName || user?.organizationName || "Organization";

    const requestedPlan = (plan === "Enterprise" ? "Enterprise" : plan === "Starter" ? "Starter" : "Professional") as "Starter" | "Professional" | "Enterprise";
    const requestedCycle = (billingCycle === "monthly" ? "monthly" : "annual") as "monthly" | "annual";

    const host = req.headers.host || "localhost:3000";
    const protocol = req.headers["x-forwarded-proto"] || "https";
    const baseUrl = process.env.APP_URL || `${protocol}://${host}`;

    // Benchmark Plan Prices (Total Amount charged per interval)
    const BENCHMARK_PLAN_PRICES = {
      Starter: { monthly: 6, annual: 50 },          // $6/month or $50/year total
      Professional: { monthly: 189, annual: 1788 },   // $189/month or $1,788/year total ($149/mo)
      Enterprise: { monthly: 849, annual: 8388 }      // $849/month or $8,388/year total ($699/mo)
    };

    const totalAmountUSD = BENCHMARK_PLAN_PRICES[requestedPlan][requestedCycle];
    const unitAmountCents = Math.round(totalAmountUSD * 100);

    console.log(`[Stripe Checkout] 1. Payment request received: plan=${requestedPlan}, cycle=${requestedCycle}, user=${finalUserId}, amount=$${totalAmountUSD}`);

    const stripe = getStripe();
    if (!stripe) {
      console.warn("[Stripe Checkout] Stripe configuration missing: STRIPE_SECRET_KEY is not defined or invalid.");
      return res.status(400).json({
        success: false,
        error: "خادم الدفع غير مهيأ حالياً (STRIPE_SECRET_KEY مفقود). يرجى التواصل مع إدارة النظام.",
        userFriendlyMessage: "خادم الدفع غير مهيأ حالياً (STRIPE_SECRET_KEY مفقود). يرجى التواصل مع إدارة النظام."
      });
    }

    // Check for duplicate active subscription
    if (user?.subscriptionStatus === "Active" && user?.stripeSubscriptionId) {
      try {
        const activeSub = await stripe.subscriptions.retrieve(user.stripeSubscriptionId);
        if (activeSub && (activeSub.status === "active" || activeSub.status === "trialing")) {
          console.warn(`[Stripe Checkout] User ${finalUserId} already has active subscription ${activeSub.id}`);
          return res.status(400).json({
            success: false,
            code: "SUBSCRIPTION_ALREADY_ACTIVE",
            error: "لديك بالفعل اشتراك نشط في منصة Zakir. يمكنك إدارة خطتك الحالية أو ترقيتها من صفحة الإعدادات.",
            userFriendlyMessage: "لديك بالفعل اشتراك نشط في منصة Zakir. يمكنك إدارة خطتك الحالية أو ترقيتها من صفحة الإعدادات."
          });
        }
      } catch (subCheckErr) {
        console.warn("[Stripe Checkout] Active subscription check notice:", subCheckErr);
      }
    }

    // Email Validator
    const isValidEmail = (emailStr?: string) => {
      if (!emailStr || typeof emailStr !== "string") return false;
      const clean = emailStr.trim().toLowerCase();
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(clean);
    };

    const validUserEmail = isValidEmail(finalUserEmail) ? finalUserEmail.trim().toLowerCase() : undefined;

    // Customer Management: Look up or create customer
    let stripeCustomerId = user?.stripeCustomerId;
    if (stripeCustomerId) {
      try {
        const existingCust = await stripe.customers.retrieve(stripeCustomerId);
        if (existingCust && !("deleted" in existingCust && existingCust.deleted)) {
          console.log(`[Stripe Checkout] Found existing Stripe Customer: ${stripeCustomerId}`);
        } else {
          stripeCustomerId = null;
        }
      } catch {
        stripeCustomerId = null;
      }
    }

    if (!stripeCustomerId && validUserEmail) {
      try {
        const newCust = await stripe.customers.create({
          email: validUserEmail,
          name: finalCompanyName,
          metadata: {
            zakirUserId: finalUserId,
            userId: finalUserId
          }
        });
        stripeCustomerId = newCust.id;
        console.log(`[Stripe Checkout] Created new Stripe Customer: ${stripeCustomerId}`);

        if (user) {
          user.stripeCustomerId = stripeCustomerId;
          writeDb(db);
        }
        try {
          await adminDb.collection("users").doc(finalUserId).set({ stripeCustomerId }, { merge: true });
        } catch (fsCustErr) {
          console.warn("[Stripe Checkout] Firestore customer id save notice:", fsCustErr);
        }
      } catch (createCustErr: any) {
        console.warn("[Stripe Checkout] Customer creation notice:", createCustErr?.message);
      }
    }

    // Price ID Resolution (Plan-Specific + Cycle-Specific)
    const planUpper = requestedPlan.toUpperCase();
    const cycleUpper = requestedCycle === "annual" ? "YEARLY" : "MONTHLY";
    const altCycleUpper = requestedCycle === "annual" ? "ANNUAL" : "MONTHLY";

    let envPriceId =
      process.env[`STRIPE_PRICE_${planUpper}_${cycleUpper}`] ||
      process.env[`STRIPE_PRICE_${planUpper}_${altCycleUpper}`];

    if (!envPriceId && requestedPlan === "Professional") {
      envPriceId = requestedCycle === "annual"
        ? (process.env.STRIPE_YEARLY_PRICE_ID || process.env.STRIPE_ANNUAL_PRICE_ID)
        : process.env.STRIPE_MONTHLY_PRICE_ID;
    }

    let resolvedPriceId: string | null = null;
    const cleanEnvPriceId = typeof envPriceId === "string" ? envPriceId.trim() : "";

    // If an authentic Stripe Price ID starting with price_ or plan_ is supplied, verify and use it
    if (cleanEnvPriceId && (cleanEnvPriceId.startsWith("price_") || cleanEnvPriceId.startsWith("plan_"))) {
      try {
        console.log(`[Stripe Checkout] Verifying configured Price ID '${cleanEnvPriceId}' with Stripe...`);
        const retrievedPrice = await stripe.prices.retrieve(cleanEnvPriceId);
        if (retrievedPrice && retrievedPrice.active && retrievedPrice.type === "recurring") {
          const expectedInterval = requestedCycle === "annual" ? "year" : "month";
          if (retrievedPrice.recurring?.interval === expectedInterval) {
            resolvedPriceId = retrievedPrice.id;
            console.log(`[Stripe Checkout] Verified Stripe Catalog Price ID: ${resolvedPriceId}`);
          }
        }
      } catch (priceCheckErr: any) {
        console.warn(`[Stripe Checkout] Configured Price ID '${cleanEnvPriceId}' could not be retrieved from Stripe (${priceCheckErr?.message}). Falling back smoothly to native in-app recurring price_data.`);
      }
    }

    // Build Line Items: Use verified price ID if available; otherwise use Stripe native dynamic price_data
    const lineItems: Stripe.Checkout.SessionCreateParams.LineItem[] = resolvedPriceId
      ? [{ price: resolvedPriceId, quantity: 1 }]
      : [{
          price_data: {
            currency: "usd",
            product_data: {
              name: `Zakir ${requestedPlan} Plan (${requestedCycle === "annual" ? "Annual Billing" : "Monthly Billing"})`,
              description: `Institutional Causal Memory Engine & Decision Intelligence Suite for ${finalCompanyName}.`,
            },
            unit_amount: unitAmountCents,
            recurring: {
              interval: requestedCycle === "annual" ? "year" : "month",
              interval_count: 1,
            },
          },
          quantity: 1,
        }];

    // Build Session Parameters with official Stripe ui_mode: "embedded", explicit payment methods, and return_url
    const returnUrl = `${baseUrl}/?view=settings&tab=subscription&session_id={CHECKOUT_SESSION_ID}`;
    const sessionParams: Stripe.Checkout.SessionCreateParams = {
      mode: "subscription",
      payment_method_types: ["card"],
      line_items: lineItems,
      client_reference_id: finalUserId,
      metadata: {
        userId: finalUserId,
        userEmail: validUserEmail || finalUserEmail || "",
        companyName: finalCompanyName,
        plan: requestedPlan,
        billingCycle: requestedCycle,
      },
      ui_mode: "embedded",
      return_url: returnUrl,
    };

    if (stripeCustomerId) {
      sessionParams.customer = stripeCustomerId;
    } else if (validUserEmail) {
      sessionParams.customer_email = validUserEmail;
    }

    console.log(`[Stripe Checkout] Creating Embedded Checkout Session for user ${finalUserId} (ui_mode: embedded, items: ${resolvedPriceId ? 'catalog' : 'dynamic price_data'})...`);
    const session: Stripe.Checkout.Session = await stripe.checkout.sessions.create(sessionParams);

    console.log(`[Stripe Checkout] Checkout Session created successfully: id=${session.id}`);

    db.stripe_sessions = db.stripe_sessions || {};
    db.stripe_sessions[session.id] = finalUserId;
    writeDb(db);

    const { publishableKey } = resolveStripeKeys();

    return res.json({
      success: true,
      sessionId: session.id,
      clientSecret: session.client_secret,
      publishableKey: publishableKey || "",
    });

  } catch (err: any) {
    const errorDetails = {
      httpMethod: req.method,
      route: req.originalUrl || req.url,
      stripeErrorType: err?.type || err?.rawType || "UnknownType",
      stripeErrorCode: err?.code || err?.raw?.code || "PAYMENT_SESSION_CREATION_FAILED",
      stripeErrorMessage: err?.message || err?.raw?.message || "Failed to initiate Stripe Checkout",
      stripeErrorParam: err?.param || err?.raw?.param,
      stripeDeclineCode: err?.decline_code || err?.raw?.decline_code,
      statusCode: err?.statusCode || 500,
    };

    console.error("[Stripe Checkout] Detailed Error in Checkout Session Creation:", errorDetails);

    const httpStatusCode =
      err?.statusCode && err?.statusCode >= 400 && err?.statusCode < 600
        ? err.statusCode
        : 500;

    res.status(httpStatusCode).json({ 
      success: false,
      code: errorDetails.stripeErrorCode,
      errorType: errorDetails.stripeErrorType,
      error: errorDetails.stripeErrorMessage,
      userFriendlyMessage: err?.message || "تعذر إعداد جلسة الدفع الآمن حالياً. يرجى المحاولة لاحقاً."
    });
  } finally {
    inFlightCheckoutUsers.delete(authUserId);
  }
});

