app.post(["/api/stripe/cancel-subscription", "/stripe/cancel-subscription"], requireAuth, async (req: AuthRequest, res) => {
  try {
    const authUserId = req.user?.uid;
    if (!authUserId) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    const stripeKeys = resolveStripeKeys();
    const isMockAuth = Boolean((req as any).isMockAuth || (req.user as any)?.isMockUser);
    const isLiveStripe = Boolean(
      stripeKeys.secretKey?.startsWith("sk_live_") || 
      stripeKeys.secretKey?.startsWith("rk_live_") ||
      stripeKeys.publishableKey?.startsWith("pk_live_")
    );
    if (isMockAuth && isLiveStripe) {
      return res.status(403).json({
        error: "Security Violation: Mock authentication cannot cancel Live Stripe subscriptions.",
        code: "MOCK_AUTH_LIVE_STRIPE_BLOCKED"
      });
    }

    const db = readDb();
    let user = db.users.find((u: any) => u.id === authUserId);
    if (!user) {
      try {
        const userDoc = await adminDb.collection("users").doc(authUserId).get();
        if (userDoc && userDoc.exists) {
          user = userDoc.data();
        }
      } catch (fsErr) {
        console.warn("[CancelSub] Firestore lookup notice:", fsErr);
      }
    }

    const stripe = getStripe();
    if (stripe && user?.stripeSubscriptionId) {
      try {
        await stripe.subscriptions.cancel(user.stripeSubscriptionId);
      } catch (stripeErr: any) {
        console.warn("Stripe cancel subscription warning:", stripeErr.message);
      }
    }

    if (user) {
      user.subscriptionStatus = "Inactive";
      user.subscriptionPlan = undefined;
      writeDb(db);
    }

    try {
      await adminDb.collection("users").doc(authUserId).set({
        subscriptionStatus: "Inactive",
        subscriptionPlan: null
      }, { merge: true });
    } catch (fsErr: any) {
      console.warn("Firestore cancel sync warning:", fsErr.message);
    }

    return res.json({ success: true, message: "تم إلغاء تجديد الاشتراك بنجاح." });
  } catch (err: any) {
    console.error("Error cancelling subscription:", err);
    res.status(500).json({ error: err.message || "Failed to cancel subscription" });
  }
});

